import 'package:flutter/material.dart';
class SoundPicker extends StatelessWidget { const SoundPicker({super.key, required this.selected, required this.onChanged}); final String selected; final ValueChanged<String> onChanged; @override Widget build(BuildContext context) => DropdownButtonFormField<String>(value: selected, decoration: const InputDecoration(labelText: 'Alarm sound'), items: const ['Signal Bell', 'Sunrise Pulse', 'Royal Horn'].map((sound) => DropdownMenuItem(value: sound, child: Text(sound))).toList(), onChanged: (value) { if (value != null) onChanged(value); }); }
